                <section class="ch2-vlan-checklist" data-dhcp-checklist hidden aria-label="Target empat DHCP Server"><div class="ch2-vlan-checklist__heading"><b>Target DHCP Server</b><span data-dhcp-task-count role="status" aria-live="polite">0 / 4 selesai</span></div><ul><li data-dhcp-task="local"><span class="ch2-vlan-task__mark" data-dhcp-task-mark="local" aria-hidden="true">1</span><div><b>DHCP PC lokal · ether3-local</b><small>192.168.100.0/24 · gateway 192.168.100.1</small><small data-dhcp-task-range="local">Rentang bawaan: 192.168.100.2-192.168.100.254</small><span class="ch2-vlan-task__status" data-dhcp-task-status="local">Belum selesai</span></div></li><li data-dhcp-task="student"><span class="ch2-vlan-task__mark" data-dhcp-task-mark="student" aria-hidden="true">2</span><div><b>DHCP siswa · vlan1-siswa</b><small>192.168.40.0/24 · gateway 192.168.40.1</small><small data-dhcp-task-range="student">Addresses to Give Out: 192.168.40.10-192.168.40.50</small><span class="ch2-vlan-task__status" data-dhcp-task-status="student">Belum selesai</span></div></li><li data-dhcp-task="teacher"><span class="ch2-vlan-task__mark" data-dhcp-task-mark="teacher" aria-hidden="true">3</span><div><b>DHCP guru · vlan2-guru</b><small>192.168.60.0/24 · gateway 192.168.60.1</small><small data-dhcp-task-range="teacher">Addresses to Give Out: 192.168.60.10-192.168.60.50</small><span class="ch2-vlan-task__status" data-dhcp-task-status="teacher">Belum selesai</span></div></li><li data-dhcp-task="wireless"><span class="ch2-vlan-task__mark" data-dhcp-task-mark="wireless" aria-hidden="true">4</span><div><b>DHCP Wi-Fi · wlan1</b><small>192.168.20.0/24 · gateway 192.168.20.1</small><small data-dhcp-task-range="wireless">Addresses to Give Out: 192.168.20.10-192.168.20.50</small><span class="ch2-vlan-task__status" data-dhcp-task-status="wireless">Belum selesai</span></div></li></ul></section>

